<?php
require_once dirname(__DIR__).'/shop.storage/legacy/views/components.php';
$exports=$isAdmin?all('SELECT e.*,o.reference,o.product_name,c.last_error AS contract_error FROM shop_vps_exports e JOIN shop_orders o ON o.id=e.order_id LEFT JOIN shop_contracts c ON c.order_id=e.order_id ORDER BY e.updated_ts DESC LIMIT 100'):all('SELECT e.*,o.reference,o.product_name FROM shop_vps_exports e JOIN shop_orders o ON o.id=e.order_id WHERE e.customer_id=? ORDER BY e.updated_ts DESC LIMIT 100',[(int)user()['id']]);
$states=['queued'=>'Sicherung vorgemerkt','building'=>'Sicherung wird vorbereitet','ready'=>'Download bereit','deleting'=>'VPS-Löschung angefragt','delete_wait'=>'VPS wird gelöscht','cleanup'=>'Sicherung wird entfernt','done'=>'Abschluss erledigt','needs_action'=>'Prüfung erforderlich'];
?>
<div class="page-heading"><div class="eyebrow"><?= $isAdmin?'INFRASTRUKTUR':'DEINE DATEN' ?></div><h1><?= $isAdmin?'VPS-Abschluss & Sicherungen':'VPS-Sicherungen' ?></h1><p>Zum Vertragsende fährt dein VPS herunter. Die vollständige Sicherung steht anschließend fünf Tage zum Download bereit. Danach werden der VPS und die Sicherung endgültig gelöscht.</p></div>
<?php if($isAdmin): $cfg=integration_row('proxmox')?integration_config('proxmox',false):[];$node=$cfg['node']??'';$runner=json_decode(shop_meta_get('vps_export_runner:'.$node,'{}'),true); ?>
<section class="panel form-panel"><h2>Sicherungsdienst auf Proxmox</h2><p><strong><?= (int)($runner['seen']??0)>time()-180?'Verbunden':'Noch kein aktuelles Lebenszeichen' ?></strong><?= !empty($runner['seen'])?' · zuletzt '.date('d.m.Y H:i T',(int)$runner['seen']):'' ?></p><p>Den Installer auf dem gespeicherten Proxmox-Host als root über die Konsole ausführen: <code>bash orga-vorlagendienst.sh</code>. Er erweitert den vorhandenen Vorlagenrunner. Für Downloads TCP-Port <strong>9444</strong> vom Shop-Webserver zum Proxmox-Host freigeben. Es ist kein SSH-Zugang im Shop erforderlich.</p><form method="post" data-download><?= csrf() ?><input type="hidden" name="action" value="template_runner_download"><button class="button button-outline">Runner installieren / aktualisieren</button></form><p class="small muted">Sicherungen werden in einem eigenen Verzeichnis auf store01 oder store02 abgelegt. Ohne bestätigte vollständige Sicherung und erreichbaren Download beginnt keine Löschfrist. Bestehende, bereits vollständig abgeschlossene Verträge werden nicht rückwirkend gelöscht. Bei unterbrochenen Sicherungen: <code>journalctl -u orga-vps-export-runner</code> prüfen; die Daten bleiben erhalten.</p></section>
<section class="panel"><h2>Automatische Storage-Auswahl</h2><p>Neue LXC-Container und VMs verwenden den geeigneten Storage mit mehr freiem Platz: <strong>store01 oder store02</strong>. Laufende Reservierungen, die vollständige bestellte Plattengröße und eine Sicherheitsreserve von 5 % (mindestens 1 GB) werden berücksichtigt. Ist der Platz nicht ausreichend oder der Vergleich nicht vollständig möglich, wird die Erstellung angehalten.</p></section>
<?php endif ?>
<?php if(!$exports): ?><section class="panel"><?php empty_state('database','Keine VPS-Sicherungen','Hier erscheinen nach dem tatsächlichen Vertragsende die Sicherungen deiner gekündigten VPS.'); ?></section><?php endif ?>
<?php foreach($exports as $export): $available=$export['state']==='ready' && shop_now()<(int)$export['expires_ts']; ?>
<section class="panel form-panel"><div class="eyebrow" style="overflow-wrap:anywhere"><?= e($export['reference']) ?></div><h2><?= e($export['product_name']) ?></h2><p><strong><?= e($export['state']==='ready' && !$available?'Downloadfrist abgelaufen':($states[$export['state']]??'Wird geprüft')) ?></strong><?php if($isAdmin): ?> · VPS <?= (int)$export['vmid'] ?> · Kunde #<?= (int)$export['customer_id'] ?><?php endif ?></p>
<?php if($export['ready_ts']): ?><dl class="detail-list"><div><dt>Bereitgestellt</dt><dd><?= date('d.m.Y H:i T',(int)$export['ready_ts']) ?></dd></div><div><dt>Download bis</dt><dd><?= date('d.m.Y H:i T',(int)$export['expires_ts']) ?></dd></div><div><dt>Archivgröße</dt><dd><?= number_format((int)$export['size_bytes']/1073741824,2,',','.') ?> GB</dd></div></dl><?php endif ?>
<?php if(!$isAdmin && $available): ?><p>Diese vollständige Proxmox-Sicherung enthält die VPS-Daten und Konfiguration. Für die Wiederherstellung wird Proxmox VE benötigt. Abgebrochene Downloads können mit einem geeigneten Downloadprogramm fortgesetzt werden.</p><a class="button button-teal" href="/konto/vps-sicherungen?download=<?= (int)$export['order_id'] ?>">VPS-Sicherung herunterladen</a><p class="small muted">SHA-256: <code style="overflow-wrap:anywhere;white-space:normal;word-break:break-all"><?= e($export['sha256']) ?></code></p><?php elseif(!$isAdmin && $export['state']!=='done'): ?><p><?= $export['expires_ts'] && shop_now()>=(int)$export['expires_ts']?'Die Downloadfrist ist abgelaufen.':'Die Sicherung wird vorbereitet. Du erhältst eine Benachrichtigung und eine E-Mail, sobald der Download bereitsteht.' ?></p><?php endif ?>
<?php if($isAdmin && $export['state']==='needs_action'): ?><form method="post"><?= csrf() ?><input type="hidden" name="action" value="vps_export_retry"><input type="hidden" name="order_id" value="<?= (int)$export['order_id'] ?>"><button class="button button-outline">Nach Prüfung erneut versuchen</button></form><?php endif ?>
<?php if($isAdmin && !empty($export['contract_error'])): ?><p class="notice notice-error"><?= e($export['contract_error']) ?></p><?php endif ?>
<?php if($isAdmin && $export['last_error']): ?><p class="notice notice-error"><?= e($export['last_error']) ?></p><?php endif ?>
</section>
<?php endforeach ?>
